const ready=(async()=>{await prior.ready;if(globalThis.indexedDB)try{const report=await reconcileArtifactStorage();globalThis.closedLoopArtifactRecoveryError=null;globalThis.closedLoopArtifactRecoveryReport=report;}catch(error){globalThis.closedLoopArtifactRecoveryError=String(error?.stack||error);console.error('Artifact recovery could not complete; byte-dependent work remains fail-closed.',error);}return true;})();

